494	// Extract the host and port from a target address
495	func extractHostPort(target string) (string, int) {
496		if idx := strings.Index(target, "://"); idx != -1 {
497			target = target[idx+3:]
498			// Ensure any leading authorities (like 8.8.8.8 in dns://8.8.8.8/foo) are stripped
499			if slashIdx := strings.Index(target, "/"); slashIdx != -1 {
500				target = target[slashIdx+1:]
501			}
502		}
503		host, portStr, err := net.SplitHostPort(target)
504		if err != nil {
505			return target, 0
506		}
507		port, err := strconv.Atoi(portStr)
508		if err != nil {
509			return host, 0
510		}
511		return host, port
512	}
