635	func logActionableError(ctx context.Context, logger *slog.Logger, info gax.TelemetryErrorInfo) {
636		baseLogAttrs := []slog.Attr{
637			slog.String("rpc.system.name", "grpc"),
638			slog.String("rpc.response.status_code", info.StatusCode),
639		}
640	
641		if resendCountStr, ok := callctx.TelemetryFromContext(ctx, "resend_count"); ok {
642			if count, e := strconv.Atoi(resendCountStr); e == nil {
643				baseLogAttrs = append(baseLogAttrs, slog.Int64("gcp.grpc.resend_count", int64(count)))
644			}
645		}
646	
647		msg := info.StatusMessage
648		if msg == "" {
649			msg = "API call failed"
650		}
651	
652		if rpcMethod, ok := callctx.TelemetryFromContext(ctx, "rpc_method"); ok {
653			baseLogAttrs = append(baseLogAttrs, slog.String("rpc.method", rpcMethod))
654		}
655	
656		if resName, ok := callctx.TelemetryFromContext(ctx, "resource_name"); ok {
657			baseLogAttrs = append(baseLogAttrs, slog.String("gcp.resource.destination.id", resName))
658		}
659	
660		if info.Domain != "" {
661			baseLogAttrs = append(baseLogAttrs, slog.String("gcp.errors.domain", info.Domain))
662		}
663		for k, v := range info.Metadata {
664			baseLogAttrs = append(baseLogAttrs, slog.String("gcp.errors.metadata."+k, v))
