117	// If TLSCertificate is available, set TLSClientConfig as well.
118	func defaultBaseTransport(clientCertSource cert.Provider, dialTLSContext func(context.Context, string, string) (net.Conn, error)) http.RoundTripper {
119		defaultTransport, ok := http.DefaultTransport.(*http.Transport)
120		if !ok {
121			defaultTransport = transport.BaseTransport()
122		}
123		trans := defaultTransport.Clone()
124		trans.MaxIdleConnsPerHost = 100
