func scratchLogger(buf *bytes.Buffer) *slog.Logger {
	return slog.New(slog.NewJSONHandler(buf, &slog.HandlerOptions{Level: slog.LevelDebug}))
}

func TestScratch_LoggingErrorInfo(t *testing.T) {
	gax.TestOnlyResetIsFeatureEnabled()
	defer gax.TestOnlyResetIsFeatureEnabled()
	t.Setenv("GOOGLE_SDK_GO_EXPERIMENTAL_LOGGING", "true")

	body := `{"error":{"code":429,"message":"quota exceeded","status":"RESOURCE_EXHAUSTED","details":[{"@type":"type.googleapis.com/google.rpc.ErrorInfo","reason":"RATE_LIMIT_EXCEEDED","domain":"example.googleapis.com","metadata":{"quota_limit":"FooBar"}}]}}`
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusTooManyRequests)
		w.Write([]byte(body))
	}))
	defer server.Close()

	var buf bytes.Buffer
	opts := &Options{DisableAuthentication: true, Endpoint: server.URL, Logger: scratchLogger(&buf)}
	client, err := NewClient(opts)
	if err != nil {
		t.Fatal(err)
	}
	ctx := callctx.WithTelemetryContext(context.Background(), "resend_count", "2")
	ctx = callctx.WithTelemetryContext(ctx, "resource_name", "my-resource")
	req, _ := http.NewRequestWithContext(ctx, "GET", server.URL, nil)
	resp, err := client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	if buf.Len() != 0 {
		t.Fatalf("log emitted before body close: %s", buf.String())
	}
	resp.Body.Close()

	lines := strings.Split(strings.TrimSpace(buf.String()), "\n")
	if len(lines) != 1 {
		t.Fatalf("want exactly 1 log record, got %d: %q", len(lines), buf.String())
	}
	var rec map[string]any
	if err := json.Unmarshal([]byte(lines[0]), &rec); err != nil {
		t.Fatal(err)
	}
	t.Logf("record: %#v", rec)
	checks := map[string]any{
		"msg":                          "quota exceeded",
		"rpc.system.name":              "http",
		"rpc.response.status_code":     "RESOURCE_EXHAUSTED",
		"http.response.status_code":    float64(429),
		"http.request.method":          "GET",
		"error.type":                   "RATE_LIMIT_EXCEEDED",
		"gcp.errors.domain":            "example.googleapis.com",
		"gcp.errors.metadata.quota_limit": "FooBar",
		"http.request.resend_count":    float64(2),
		"gcp.resource.destination.id":  "my-resource",
		"level":                        "DEBUG",
	}
	for k, want := range checks {
		if got := rec[k]; got != want {
			t.Errorf("field %q = %#v, want %#v", k, got, want)
		}
	}
}

