func TestScratch_TimeoutAndLargeBody(t *testing.T) {
	gax.TestOnlyResetIsFeatureEnabled()
	defer gax.TestOnlyResetIsFeatureEnabled()
	t.Setenv("GOOGLE_SDK_GO_EXPERIMENTAL_LOGGING", "true")

	// Large body with known ContentLength > 8192.
	large := strings.Repeat("x", 9000)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Length", "9000")
		w.WriteHeader(http.StatusBadRequest)
		w.Write([]byte(large))
	}))
	defer server.Close()

	var buf bytes.Buffer
	opts := &Options{DisableAuthentication: true, Endpoint: server.URL, Logger: scratchLogger(&buf)}
	client, _ := NewClient(opts)
	req, _ := http.NewRequest("GET", server.URL, nil)
	resp, err := client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	// For large ContentLength, log should be emitted immediately (before close),
	// and body must NOT be an *errorTrackingBody.
	if _, ok := resp.Body.(*errorTrackingBody); ok {
		t.Errorf("large body should not be wrapped in *errorTrackingBody")
	}
	if buf.Len() == 0 {
		t.Fatalf("expected immediate log for large ContentLength")
	}
	var rec map[string]any
	json.Unmarshal([]byte(strings.TrimSpace(buf.String())), &rec)
	if rec["msg"] != "400 Bad Request" {
		t.Errorf("large body msg = %#v, want status string", rec["msg"])
	}
	resp.Body.Close()
}
